/**
 * 严格按照标准球面墨卡托与阿里 DataV 中国地图高精矢量轮廓构建
 * 包含中国 34 个省级行政区、南海诸岛十段线与主要水系
 */
export function projectGeoPoint(lng: number, lat: number): [number, number] {
  const x = 45 + ((lng - 73.2) / (135.5 - 73.2)) * 710
  const rad = (lat * Math.PI) / 180
  const mercY = Math.log(Math.tan(Math.PI / 4 + rad / 2))
  const minMerc = Math.log(Math.tan(Math.PI / 4 + (17.5 * Math.PI) / 360))
  const maxMerc = Math.log(Math.tan(Math.PI / 4 + (54.0 * Math.PI) / 360))
  const y = 570 - ((mercY - minMerc) / (maxMerc - minMerc)) * 520
  return [Math.round(x * 10) / 10, Math.round(y * 10) / 10]
}

